<?php $__env->startSection('content'); ?><div class="page-head"><div><div class="eyebrow">CLIENT MANAGEMENT</div><h1>Businesses</h1><p>Manage assigned businesses, compliance and payment history.</p></div><a class="btn primary" href="<?php echo e(route('businesses.create')); ?>">+ New Business</a></div><div class="panel"><form class="toolbar"><input name="q" value="<?php echo e(request('q')); ?>" placeholder="Search businesses..."><button class="btn secondary">Search</button></form><div class="table-wrap"><table><thead><tr><th>Business</th><th>Contact</th><th>Users</th><th>Cards</th><th>Payments</th><th>Status</th><th></th></tr></thead><tbody><?php $__currentLoopData = $businesses; $__env->addLoop($__currentLoopData); foreach($__currentLoopData as $b): $__env->incrementLoopIndices(); $loop = $__env->getLastLoop(); ?><tr><td><a class="link" href="<?php echo e(route('businesses.show',$b)); ?>"><strong><?php echo e($b->name); ?></strong></a><small><?php echo e($b->email); ?></small></td><td><?php echo e($b->contact_person); ?><br><small><?php echo e($b->phone); ?></small></td><td><?php echo e($b->users_count); ?></td><td><?php echo e($b->cards_count); ?></td><td><?php echo e($b->payments_count); ?></td><td><span class="badge <?php echo e($b->status==='active'?'success':'neutral'); ?>"><?php echo e(ucfirst($b->status)); ?></span></td><td><a class="btn tiny" href="<?php echo e(route('businesses.edit',$b)); ?>">Edit</a></td></tr><?php endforeach; $__env->popLoop(); $loop = $__env->getLastLoop(); ?></tbody></table></div><div class="pagination"><?php echo e($businesses->links()); ?></div></div><?php $__env->stopSection(); ?>

